/*
 * The UI font: Spleen 12x24, printable ASCII only, each character a
 * FONT_W x FONT_H bitmap. The glyphs are in font.c, generated by
 * mk/font-gen.py from the BDF (BSD 2-Clause, see font.c).
 */
#ifndef UI_FONT_H
#define UI_FONT_H

#include <stdint.h>

#define FONT_W     12
#define FONT_H     24
#define FONT_FIRST 0x20
#define FONT_LAST  0x7e

/* One uint16_t a row, top to bottom; bit 15 is the leftmost pixel. */
extern const uint16_t font_glyphs[FONT_LAST - FONT_FIRST + 1][FONT_H];

#endif
